def operation(n):
    """Applies the operation: floor(n/10) + 3 * (n mod 10)"""
    if n < 0:
        raise ValueError("Input must be non-negative")
    return (n // 10) + 3 * (n % 10)

def simulate_sequence(start_n, max_steps=1000):
    """Simulates the sequence for a given starting number, looking for cycles."""
    sequence = []
    seen = {} # value -> step number
    current = start_n

    for step in range(max_steps):
        if current in seen:
            cycle_start_step = seen[current]
            cycle_length = step - cycle_start_step
            # Return sequence up to cycle detection + cycle length
            return sequence + [current] * cycle_length, cycle_start_step, cycle_length

        seen[current] = step
        sequence.append(current)
        current = operation(current)

    # If no cycle found within max_steps
    return sequence, None, None

# Dictionary to store observations for n=1 to 100
observations = {}

# Track the main cycle found during manual check/initial run
main_cycle_sequence = [2, 6, 18, 25, 17, 22, 8, 24, 14, 13, 10, 1, 3, 9, 27, 23, 11, 4, 12, 7, 21, 5, 15, 16, 19, 28, 26, 20]
print(f"Verified Cycle: {main_cycle_sequence}")


for n in range(1, 101):
    # We use the cycle detection function for rigorous checking
    try:
        sequence, start_step, cycle_length = simulate_sequence(n)

        if cycle_length is not None:
            observations[n] = {
                "type": "Cycle",
                "cycle_length": cycle_length,
                "pre_period_length": start_step,
                "cycle_elements": sequence[start_step:]
            }
        elif len(sequence) >= 100:
             observations[n] = {"type": "Long Sequence", "length": len(sequence)}
        else:
             observations[n] = {"type": "Terminates/Converges (or max_steps reached)", "sequence": sequence}

    except Exception as e:
        observations[n] = {"error": str(e)}

# --- Summarizing Results ---
cycle_details = {n: data for n, data in observations.items() if data.get("type") == "Cycle"}

# Extracting a few key findings for the note
print("\n--- Summary of Findings ---")
print(f"Total numbers analyzed (1-100): {len(observations)}")
print(f"Number of starting values that enter a cycle: {len(cycle_details)}")

# Report the main cycle found for consistency check
